cd /workspace && cat > src/main.rs << 'EOF'
use clap::{Parser, ValueEnum};
use std::fs;
use std::io::{self, Read};
use std::path::Path;
use std::process::{Command, Stdio};

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(about = "Universal multi-language runner and REPL")]
#[command(version)]
#[command(args_conflicts_with_subcommands = true)]
struct Args {
    /// Positional arguments (language, code, or file)
    #[arg(trailing_var_arg = true)]
    args: Vec<String>,

    /// Explicitly choose the language to execute
    #[arg(short, long)]
    lang: Option<String>,

    /// Execute code from the provided file path
    #[arg(short, long)]
    file: Option<String>,

    /// Execute the provided code snippet
    #[arg(short, long)]
    code: Option<String>,

    /// Disable heuristic language detection
    #[arg(long)]
    no_detect: bool,
}

fn detect_language_from_extension(path: &str) -> Option<String> {
    if let Some(ext) = Path::new(path).extension() {
        if let Some(ext_str) = ext.to_str() {
            return match ext_str {
                "py" => Some("python".to_string()),
                "sh" => Some("bash".to_string()),
                "bash" => Some("bash".to_string()),
                "rb" => Some("ruby".to_string()),
                "go" => Some("go".to_string()),
                "rs" => Some("rust".to_string()),
                "js" => Some("javascript".to_string()),
                "ts" => Some("typescript".to_string()),
                "pl" => Some("perl".to_string()),
                "php" => Some("php".to_string()),
                "java" => Some("java".to_string()),
                "c" => Some("c".to_string()),
                "cpp" | "cc" | "cxx" => Some("cpp".to_string()),
                _ => None,
            };
        }
    }
    None
}

fn get_interpreter(lang: &str) -> Option<&'static str> {
    match lang.to_lowercase().as_str() {
        "python" | "python3" | "py" => Some("python3"),
        "bash" | "sh" | "shell" => Some("bash"),
        "perl" | "pl" => Some("perl"),
        "ruby" | "rb" => Some("ruby"),
        "go" => Some("go"),
        "rust" | "rs" => Some("rustc"),
        "javascript" | "js" | "node" => Some("node"),
        "typescript" | "ts" => Some("ts-node"),
        "php" => Some("php"),
        "java" => Some("java"),
        "c" => Some("gcc"),
        "cpp" | "cc" | "cxx" => Some("g++"),
        _ => None,
    }
}

fn execute_code(lang: &str, code: &str, file_path: Option<&str>) -> io::Result<()> {
    let interpreter = get_interpreter(lang)
        .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, 
            format!("No such file or directory (os error 2)")))?;

    // Read stdin if available
    let mut stdin_data = String::new();
    let stdin = io::stdin();
    if atty::is(atty::Stream::Stdin) {
        // Terminal is a TTY, no stdin piped
    } else {
        // stdin is piped, read it
        stdin.read_to_string(&mut stdin_data)?;
    }

    match lang.to_lowercase().as_str() {
        "python" | "python3" | "py" => {
            let mut cmd = Command::new(interpreter)
                .arg("-c")
                .arg(code)
                .stdin(Stdio::piped())
                .spawn()?;

            if let Some(mut child_stdin) = cmd.stdin.take() {
                use std::io::Write;
                let _ = child_stdin.write_all(stdin_data.as_bytes());
            }

            let status = cmd.wait()?;
            std::process::exit(status.code().unwrap_or(1));
        },
        "bash" | "sh" | "shell" => {
            let mut cmd = Command::new(interpreter)
                .arg("-c")
                .arg(code)
                .stdin(Stdio::piped())
                .spawn()?;

            if let Some(mut child_stdin) = cmd.stdin.take() {
                use std::io::Write;
                let _ = child_stdin.write_all(stdin_data.as_bytes());
            }

            let status = cmd.wait()?;
            std::process::exit(status.code().unwrap_or(1));
        },
        "perl" | "pl" => {
            let mut cmd = Command::new(interpreter)
                .arg("-e")
                .arg(code)
                .stdin(Stdio::piped())
                .spawn()?;

            if let Some(mut child_stdin) = cmd.stdin.take() {
                use std::io::Write;
                let _ = child_stdin.write_all(stdin_data.as_bytes());
            }

            let status = cmd.wait()?;
            std::process::exit(status.code().unwrap_or(1));
        },
        "ruby" | "rb" => {
            let mut cmd = Command::new(interpreter)
                .arg("-e")
                .arg(code)
                .stdin(Stdio::piped())
                .spawn()?;

            if let Some(mut child_stdin) = cmd.stdin.take() {
                use std::io::Write;
                let _ = child_stdin.write_all(stdin_data.as_bytes());
            }

            let status = cmd.wait()?;
            std::process::exit(status.code().unwrap_or(1));
        },
        "go" => {
            // Go needs a file
            if let Some(file) = file_path {
                let mut cmd = Command::new("go")
                    .arg("run")
                    .arg(file)
                    .stdin(Stdio::piped())
                    .spawn()?;

                if let Some(mut child_stdin) = cmd.stdin.take() {
                    use std::io::Write;
                    let _ = child_stdin.write_all(stdin_data.as_bytes());
                }

                let status = cmd.wait()?;
                std::process::exit(status.code().unwrap_or(1));
            } else {
                return Err(io::Error::new(io::ErrorKind::NotFound, 
                    "Go requires a file to execute"));
            }
        },
        _ => {
            return Err(io::Error::new(io::ErrorKind::NotFound, 
                format!("No such file or directory (os error 2)")));
        }
    }
}

fn execute_file(file_path: &str, lang: Option<&str>) -> io::Result<()> {
    let content = fs::read_to_string(file_path)?;
    let detected_lang = if lang.is_none() {
        detect_language_from_extension(file_path)
    } else {
        lang.map(|s| s.to_string())
    };

    if let Some(language) = detected_lang {
        // For Go, pass the file path directly
        if language.to_lowercase() == "go" {
            let mut stdin_data = String::new();
            let stdin = io::stdin();
            if !atty::is(atty::Stream::Stdin) {
                stdin.read_to_string(&mut stdin_data)?;
            }

            let mut cmd = Command::new("go")
                .arg("run")
                .arg(file_path)
                .stdin(Stdio::piped())
                .spawn()?;

            if let Some(mut child_stdin) = cmd.stdin.take() {
                use std::io::Write;
                let _ = child_stdin.write_all(stdin_data.as_bytes());
            }

            let status = cmd.wait()?;
            std::process::exit(status.code().unwrap_or(1));
        } else {
            // For other languages, execute the content as code
            execute_code(&language, &content, Some(file_path))?;
        }
    } else {
        return Err(io::Error::new(io::ErrorKind::NotFound, 
            "Could not detect language"));
    }

    Ok(())
}

fn main() {
    let args = Args::parse();

    // Handle --version (it's handled by clap)

    // Determine what to execute
    if let Some(code) = &args.code {
        // Execute code directly
        let lang = if let Some(lang) = &args.lang {
            lang.clone()
        } else {
            return;
        };

        if let Err(e) = execute_code(&lang, code, None) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else if let Some(file_path) = &args.file {
        // Execute file
        if let Err(e) = execute_file(file_path, args.lang.as_deref()) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else if !args.args.is_empty() {
        // Handle positional arguments
        if args.args.len() == 1 {
            // Single argument - could be a file path
            let arg = &args.args[0];
            if Path::new(arg).exists() {
                // It's a file
                if let Err(e) = execute_file(arg, args.lang.as_deref()) {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            } else {
                return;
            }
        } else if args.args.len() >= 2 {
            // Multiple arguments: first is language, second is code
            let lang = &args.args[0];
            let code = &args.args[1];

            if let Err(e) = execute_code(lang, code, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else if args.no_detect {
        // REPL mode - not implemented
    } else {
        // REPL mode
    }
}
EOF

