                std::process::exit(0);
            }
        } else if args.positional.len() >= 2 {
            // Multiple arguments: first is language, second is code
            let lang = &args.positional[0];
            let code = &args.positional[1];

            if let Err(e) = execute_code(lang, code, None) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        // REPL mode - just exit
        std::process::exit(0);
    }
}
